export function drawEquipment(c,g,reduced=false){const e=g.equipment,p=g.player;if(!e)return;const s=e.strike,w=e.weapon;if(w||s){const id=s?.id||w.id,u=s?Math.sin(s.age/.22*Math.PI):0;c.save();c.translate(p.x+14,p.y+18);c.scale(p.face,1);c.rotate(-.6+u*1.1);c.fillStyle='#354c65';c.fillRect(7,-5,23,10);c.fillStyle='#efc38c';c.fillRect(27,-4,28,7);c.fillStyle='#e7f5df';if(id==='scraper')c.fillRect(52,-13,22,25);else if(id==='heatgun'){c.fillStyle='#c98669';c.fillRect(8,-10,36,18);c.fillStyle='#e5c89e';c.fillRect(44,-7,14,12);}else{c.fillStyle=(w?.uses??0)<2?'#bfa1a0':'#e7f5df';c.fillRect(55,-2,5+(w?.uses??0)*3,3);}if(s){c.strokeStyle='#ffe3ad';c.lineWidth=3;c.beginPath();c.arc(0,0,s.range*.7,-.6,1);c.stroke();if(id==='heatgun'&&!reduced){c.fillStyle='#f0b07755';c.beginPath();c.moveTo(60,0);c.lineTo(s.range,40);c.lineTo(s.range,-35);c.fill();}}c.restore();}
 if(e.overload>0){c.fillStyle='#ffcb94';c.font='bold 13px monospace';c.textAlign='center';c.fillText('OVERLOAD',p.x+14,p.y-65);}
}
